sys_script.script:
(function executeRule(current, previous /*null when async*/) {
    // FLEET-16: one license per employee; expiration after today on insert; maintain is_valid
    var today = new GlideDateTime().getLocalDate().getValue();
    var exp = current.getValue('expiration_date');

    var dup = new GlideRecord('x_1850693_enterp_0_driver_license');
    dup.addQuery('employee', current.getValue('employee'));
    dup.addQuery('sys_id', '!=', current.getUniqueValue());
    dup.setLimit(1);
    dup.query();
    if (dup.hasNext()) {
        gs.addErrorMessage('This employee already has a driver license record.');
        current.setAbortAction(true);
        return;
    }

    if (current.isNewRecord() && exp && exp <= today) {
        gs.addErrorMessage('Expiration Date must be after today.');
        current.setAbortAction(true);
        return;
    }

    current.setValue('is_valid', !!exp && exp > today);
})(current, previous);
